-- profile: dms
-- Generated by DMS, never stowed: dms.colors, dms.layout, dms.input,
-- dms.windowrules, dms.outputs (each optional until DMS has run once).
-- Tracked: dms.binds, the developers' default keybinds (see notes/dms-defaults.txt).
for _, mod in ipairs({
    "dms.colors",
    "dms.layout",
    "dms.input",
    "dms.windowrules",
    "dms.outputs",
    "dms.binds",
}) do
    package.loaded[mod] = nil
    local ok, err = pcall(require, mod)
    if not ok then
        print("active_profile: " .. tostring(err))
    end
end
